'use strict';
const C=WordJournal;
const KEY='read-and-keep-demo-v1';
const $=(s,scope=document)=>scope.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Tabler Icons (MIT), stored locally so icons do not depend on a CDN.
const iconNames=new Set(['book','logo','sun','repeat','plus','arrow','chevron','calendar','star','check','close','search','leaf','settings','edit','download','trash','note','clock','spark','undo','user','cloud','upload']);
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><use href="assets/icons.svg#${iconNames.has(name)?name:'book'}"></use></svg>`;}
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
let state,storageOK=true;
try{const raw=localStorage.getItem(KEY);state=raw?JSON.parse(raw):null;if(state&&(!Array.isArray(state.entries)||state.entries.some(e=>typeof e.word!=='string'||typeof e.due!=='string')))throw new Error('Invalid data');}catch(e){storageOK=false;state=null;}
if(!state)state={entries:C.seed(),settings:{interval:3,batch:5},lastEntry:null};
state.settings={interval:3,batch:5,...state.settings};
initializeReader();
let route='today',filter='all',groupBy='date',query='',sourceFilter='',notebookFilter='',session=null,toastTimer;
let draft={mode:'batch',source:'',batch:'',paragraph:'',selected:{}};
let dialogState=null;
let persistedState=JSON.parse(JSON.stringify(state));
function persist(){try{if(window.CloudSession)window.CloudSession.save(state);else localStorage.setItem(KEY,JSON.stringify(state));persistedState=JSON.parse(JSON.stringify(state));storageOK=true;return true;}catch(e){state=JSON.parse(JSON.stringify(persistedState));storageOK=false;toast('暂时无法保存：'+(e.message||'请导出备份以免丢失'));return false;}}
if(storageOK)persist();
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3200);}
function today(){return C.dateKey();}
function shortDate(key){const p=key.split('-');return `${Number(p[1])} 月 ${Number(p[2])} 日`;}
function dateLabel(key){return key===today()?'今天':key===C.addDays(today(),-1)?'昨天':shortDate(key);}
function dateGroupLabel(key){const label=dateLabel(key),date=shortDate(key);return label===date?date:`${label} · ${date}`;}
function countWords(){return new Set(state.entries.map(e=>C.normalize(e.word))).size;}
function sourceGroups(){const map=new Map();state.entries.slice().sort((a,b)=>b.created.localeCompare(a.created)).forEach(e=>{if(!map.has(e.source))map.set(e.source,{name:e.source,date:e.created,items:[]});map.get(e.source).items.push(e);});return [...map.values()];}
function sentenceHTML(e){if(!e.sentence)return '<span class="muted">暂无原句</span>';const escapedWord=e.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const re=new RegExp('('+escapedWord+')','gi');return e.sentence.split(re).map((s,i)=>i%2?`<mark>${esc(s)}</mark>`:esc(s)).join('');}
function navHTML(){return [['today','sun','今天'],['read','note','文章选词'],['library','book','生词本'],['review','repeat','回顾']].map(([id,i,label])=>`<a href="#${id}" class="nav-btn ${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('');}
function footer(){return `<footer class="page-footer"><button class="text-link" data-action="about">关于拾词</button></footer>`;}
function intro(kicker,title,subtitle,action=''){return `<div class="page-intro"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${action||`<div class="date-label">${icon('calendar')}${shortDate(today())} · 星期${'日一二三四五六'[new Date().getDay()]}</div>`}</div>`;}
function wordCard(e){const managing=route==='library'&&bulkMode;const seen=state.entries.filter(x=>C.normalize(x.word)===C.normalize(e.word)).length;return `<article class="word-card ${managing&&bulkSelected.has(e.id)?'bulk-selected':''}" data-entry="${esc(e.id)}"><div class="word-top">${managing?`<label class="bulk-word-choice"><input type="checkbox" data-bulk-entry="${esc(e.id)}" aria-label="选择 ${esc(e.word)}，${esc(e.source)}，${shortDate(e.created)}" ${bulkSelected.has(e.id)?'checked':''}><span class="word">${esc(e.word)}</span></label>`:`<button class="word-link" data-action="detail" data-id="${esc(e.id)}" aria-label="查看 ${esc(e.word)}"><span class="word">${esc(e.word)}</span></button><button class="icon-btn ${e.star?'starred':''}" data-action="star" data-id="${esc(e.id)}" aria-label="${e.star?'取消收藏':'收藏'} ${esc(e.word)}" aria-pressed="${e.star}">${icon('star')}</button>`}</div>${e.phonetic?`<div class="phonetic">${esc(e.phonetic)}</div>`:''}<div class="meaning">${esc(e.meaning)||'<span class="muted">释义待补充</span>'}</div><p class="sentence">${sentenceHTML(e)}</p><div class="card-footer"><span class="source">${icon('book')}<span>${esc(e.source)}</span></span>${seen>1?`<span class="seen-tag">遇见 ${seen} 次</span>`:e.level==='familiar'?'<span class="seen-tag">已熟悉</span>':''}</div></article>`;}
function weekHTML(){const weekday=new Date().getDay()||7;const start=C.addDays(today(),1-weekday);return Array.from({length:7},(_,i)=>{const key=C.addDays(start,i);const done=state.entries.some(e=>e.created===key);return `<div class="day-cell"><div class="day-circle ${key===today()?'current':done?'done':''}">${done?icon('check'):'一二三四五六日'[i]}</div><span>${Number(key.slice(-2))}</span></div>`;}).join('');}
function home(){
  const books=C.notebooks(state),due=C.dueEntries(state.entries),groups=sourceGroups();
  const weekStart=C.addDays(today(),-6),weekSources=new Set(state.entries.filter(e=>e.created>=weekStart).map(e=>e.source)).size;
  return `${intro('','今天',`${shortDate(today())} · 星期${'日一二三四五六'[new Date().getDay()]}`,`<button class="btn primary record-button" data-action="add">${icon('plus')}记录生词</button>`)}
    <section class="overview" aria-label="学习概览">
      <div class="review-banner">
        <div class="banner-copy"><h2>${icon('repeat')}今日回顾</h2><div class="review-total"><strong>${due.length}</strong><span>条待回顾</span></div><button class="btn primary" data-action="start-review">${due.length?'开始回顾':'自由翻阅'}${icon('arrow')}</button></div>
        <img class="growth-art" src="assets/reading-growth.png" width="256" height="256" alt="" fetchpriority="high">
      </div>
      <div class="summary-card"><h2 class="summary-title">学习记录${icon('calendar')}</h2><div class="stats"><div class="stat"><strong>${countWords()}</strong><span>累计生词</span></div><div class="stat"><strong>${weekSources}</strong><span>近 7 天文章</span></div></div><div class="week" aria-label="本周记录">${weekHTML()}</div></div>
    </section>
    <a class="reader-home-entry" href="#read"><span class="entry-symbol">${icon('note')}</span><span><strong>文章选词</strong><small>PDF / TXT / 粘贴文本</small></span><span class="entry-action">导入文章${icon('arrow')}</span></a>
    <div class="content-layout"><section aria-label="词汇册"><div class="section-heading"><h2>词汇册<span class="count">${books.length}</span></h2><a class="text-link" href="#library">全部生词${icon('arrow')}</a></div>${books.length?`<div class="notebook-grid">${books.map(notebookCard).join('')}</div>`:empty('暂无词汇册','','导入文章','import-article')}</section>
    <aside class="trail"><div class="section-heading"><h2>最近文章</h2><span class="muted small">${groups.length} 篇</span></div><div class="trail-list">${groups.slice(0,3).map(g=>`<button class="trail-item" data-action="source" data-source="${esc(g.name)}"><span class="trail-num">${icon('book')}</span><span class="trail-text"><strong>${esc(g.name)}</strong><span>${dateLabel(g.date)} · ${g.items.length} 条生词</span></span>${icon('chevron')}</button>`).join('')||'<p class="small muted">暂无文章</p>'}</div></aside></div>${footer()}`;
}
function empty(title,description,label,action){return `<div class="empty">${icon('book')}<h2>${title}</h2>${description?`<p>${description}</p>`:''}${label?`<button class="btn primary" data-action="${action}">${label}${icon('arrow')}</button>`:''}</div>`;}
function notebookDate(book){
  const value=new Date(book.createdAt);
  return String(book.createdAt).includes('T')&&!Number.isNaN(value.getTime())?value.toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}):shortDate(book.created);
}
function notebookCard(book){
  const preview=[...new Set(book.entries.map(e=>e.word))].slice(0,3);
  return `<a class="notebook-card" href="#library?book=${encodeURIComponent(book.id)}" aria-label="打开词汇册 ${esc(book.title)}，${book.entries.length} 条词汇"><div class="notebook-cover" aria-hidden="true"><span class="notebook-kind">${icon('book')}${esc(book.kind)}</span><div class="notebook-total"><strong>${book.entries.length}</strong><span>条词汇</span></div><div class="notebook-preview">${preview.map(word=>`<span>${esc(word)}</span>`).join('')}</div></div><div class="notebook-card-body"><h3>${esc(book.title)}</h3><div class="notebook-meta"><time datetime="${esc(book.createdAt)}">${esc(notebookDate(book))}</time>${icon('arrow')}</div></div></a>`;
}
function currentNotebook(){return notebookFilter?C.notebooks(state).find(book=>book.id===notebookFilter):null;}
function libraryEntries(){return notebookFilter?currentNotebook()?.entries||[]:state.entries;}
function filteredEntries(){const q=query.trim().toLowerCase();return libraryEntries().filter(e=>(filter==='all'||filter==='starred'&&e.star||filter==='familiar'&&e.level==='familiar')&&(!sourceFilter||e.source===sourceFilter)&&(!q||[e.word,e.meaning,e.source,e.sentence,e.note].join(' ').toLowerCase().includes(q))).sort((a,b)=>b.created.localeCompare(a.created));}
function libraryResults(){const entries=filteredEntries(),controls=bulkMode?bulkControls(entries):'';if(!entries.length){const book=currentNotebook();return controls+(book&&!book.entries.length?empty('本册暂无词汇','',book.articleId?'去文章选词':'',book.articleId?'notebook-read':''):empty('没有匹配的生词','','清除筛选','clear-filters'));}const groups=new Map();entries.forEach(e=>{const key=groupBy==='date'?e.created:e.source;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(e);});return controls+`<div class="small muted" role="status">找到 ${entries.length} 条阅读记录</div>`+[...groups].map(([key,items])=>`<section><h2 class="group-title">${groupBy==='date'?dateGroupLabel(key):esc(key)}<span>${items.length} 条记录</span></h2><div class="library-grid">${items.map(wordCard).join('')}</div></section>`).join('');}
function library(){
  const book=currentNotebook(),entries=libraryEntries();
  const breadcrumb=notebookFilter?`<div class="notebook-breadcrumb"><a class="text-link" href="#today">${icon('book')}词汇册</a><span>/</span><span>${esc(book?.title||'未找到词汇册')}</span><a class="text-link" href="#library">全部生词${icon('arrow')}</a></div>`:'';
  if(notebookFilter&&!book)return `${breadcrumb}${empty('词汇册已不存在','本册可能已被移除，或不属于当前账号。')}${footer()}`;
  const title=book?esc(book.title):'生词本';
  const meta=book?`${entries.length} 条词汇 · ${esc(notebookDate(book))}`:`${countWords()} 个生词 · ${state.entries.length} 条记录`;
  const actions=`<div class="library-intro-actions">${book?.articleId?`<button class="btn soft" data-action="notebook-read">${icon('book')}打开文章</button>`:''}<button class="btn ${bulkMode?'soft':''}" data-bulk="toggle" aria-pressed="${bulkMode}">${icon(bulkMode?'check':'settings')}${bulkMode?'完成管理':'批量管理'}</button><button class="btn" data-action="export">${icon('download')}导出备份</button></div>`;
  return `${breadcrumb}${intro('',title,meta,actions)}${book?.legacy&&book.kind!=='示例词汇'?'<p class="notebook-legacy-note">旧记录未保存批次，已按来源和日期归册。</p>':''}<div class="library-toolbar"><label class="search-wrap">${icon('search')}<input id="search" type="search" aria-label="搜索单词、释义或原句" placeholder="搜索单词、释义或原句…" value="${esc(query)}"></label>${book?'':`<select id="source-filter" aria-label="筛选阅读文章"><option value="">全部阅读文章</option>${librarySourceOptions().map(g=>`<option ${g.name===sourceFilter?'selected':''} value="${esc(g.name)}">${esc(g.name)}</option>`).join('')}</select>`}</div><div class="filter-row"><div class="pills">${[['all','全部记录'],['starred','已收藏'],['familiar','已熟悉']].map(([id,label])=>`<button class="pill ${filter===id?'active':''}" data-action="filter" data-filter="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div>${book?'':`<div class="sort-toggle"><button data-action="group" data-group="date" class="${groupBy==='date'?'active':''}" aria-pressed="${groupBy==='date'}">按日期</button><button data-action="group" data-group="source" class="${groupBy==='source'?'active':''}" aria-pressed="${groupBy==='source'}">按文章</button></div>`}</div><div id="library-results">${libraryResults()}</div>${footer()}`;
}
function beginSession(free=false){const list=free?state.entries:C.dueEntries(state.entries);session={ids:list.slice(0,state.settings.batch).map(e=>e.id),index:0,history:[],free};}
function review(){if(!session)beginSession();const due=C.dueEntries(state.entries);const header=intro('','回顾','',`<button class="btn" data-action="settings">${icon('settings')}回顾设置</button>`);if(!session.ids.length)return `${header}<div class="review-wrap">${empty('今日回顾已完成','新生词将于明天加入回顾。',state.entries.length?'自由翻阅':'记录生词',state.entries.length?'free-review':'add')}</div>${footer()}`;if(session.index>=session.ids.length)return `${header}<div class="review-wrap"><div class="session-finish">${icon('leaf')}<h2>回顾完成</h2><p>本次已回顾 ${session.ids.length} 条</p>${due.length?`<button class="btn primary" data-action="next-session">再翻 ${Math.min(due.length,state.settings.batch)} 条 ${icon('arrow')}</button>`:''}<a href="#library" class="btn ${due.length?'':'primary'}">打开生词本 ${icon('book')}</a></div>${session.history.length?'<button class="session-undo" data-action="undo-review">撤销上一条回顾</button>':''}</div>${footer()}`;const e=state.entries.find(e=>e.id===session.ids[session.index]);if(!e){session.index++;return review();}return `${header}<div class="review-wrap"><div class="review-topline"><span>${session.free?'自由翻阅':'今日回顾'} · ${session.index+1} / ${session.ids.length}</span>${session.history.length?'<button class="session-undo" data-action="undo-review">撤销上一条</button>':''}</div><div class="progress-track" role="progressbar" aria-label="本次回顾进度" aria-valuemin="0" aria-valuemax="${session.ids.length}" aria-valuenow="${session.index}"><div class="progress-fill" style="width:${session.index/session.ids.length*100}%"></div></div><article class="review-card"><div class="word-top"><span class="word">${esc(e.word)}</span><button class="icon-btn ${e.star?'starred':''}" data-action="star" data-id="${e.id}" aria-label="${e.star?'取消收藏':'收藏'} ${esc(e.word)}" aria-pressed="${e.star}">${icon('star')}</button></div>${e.phonetic?`<p class="phonetic">${esc(e.phonetic)}</p>`:''}<p class="meaning">${esc(e.meaning)||'释义待补充'}</p><div class="review-context"><div class="context-label">原文</div><p class="sentence">${sentenceHTML(e)}</p><div class="source">${icon('book')}<span>${esc(e.source)} · ${dateLabel(e.created)}记录</span></div></div>${e.note?`<p class="note-line">${icon('note')}${esc(e.note)}</p>`:''}<button class="text-link" data-action="detail" data-id="${e.id}">查看详情 ${icon('arrow')}</button></article><div class="review-actions"><button class="btn" data-action="rate" data-choice="again">稍后再看<small>1 天后</small></button><button class="btn primary" data-action="rate" data-choice="read">已翻阅<small>${state.settings.interval} 天后</small></button><button class="btn" data-action="rate" data-choice="less">减少出现<small>7 天后</small></button></div></div>${footer()}`;}
function render(){const [page,params='']=location.hash.slice(1).split('?');route=['today','read','library','review'].includes(page)?page:'today';const nextNotebook=route==='library'?new URLSearchParams(params).get('book')||'':'';if(nextNotebook!==notebookFilter){query='';sourceFilter='';filter='all';bulkMode=false;bulkSelected.clear();}notebookFilter=nextNotebook;document.body.dataset.page=route;$('#desktop-nav').innerHTML=navHTML();$('#mobile-nav').innerHTML=navHTML();$('#main').innerHTML=route==='today'?home():route==='read'?readerPage():route==='library'?library():review();$('#brand-icon').innerHTML=icon('logo');hydrateIcons();readerAfterRender();bulkAfterRender();window.CloudSession?.refreshStatus();}
function navigate(next){if(location.hash==='#'+next)render();else location.hash=next;}
function showDialog(title,body){const d=$('#modal');$('#modal-content').innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="关闭弹窗">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!d.open)d.showModal();}
function closeDialog(){ $('#modal').close();dialogState=null;}
function addDialog(){dialogState='add';showDialog('记录生词',`<form id="add-form"><div class="form-row"><label for="entry-source">阅读文章 <small>选填</small></label><input id="entry-source" name="source" maxlength="150" placeholder="例如：The future of our cities" value="${esc(draft.source)}"></div><div class="segmented" aria-label="录入方式"><button type="button" data-action="add-mode" data-mode="batch" class="${draft.mode==='batch'?'active':''}" aria-pressed="${draft.mode==='batch'}">批量记词</button><button type="button" data-action="add-mode" data-mode="paragraph" class="${draft.mode==='paragraph'?'active':''}" aria-pressed="${draft.mode==='paragraph'}">从原句选词</button></div>${draft.mode==='batch'?`<div class="form-row"><label for="batch-input">生词清单</label><textarea id="batch-input" name="batch" rows="5" maxlength="20000" placeholder="每行一个词，也可以带上释义和原句：&#10;sustain | 维持；支撑 | The region cannot sustain its current population.&#10;urban sprawl | 城市蔓延">${esc(draft.batch)}</textarea><p class="field-hint">支持单词和短语。用 | 分隔词语、释义、原句。</p></div>`:`<div class="form-row"><label for="paragraph-input">粘贴阅读原文</label><textarea id="paragraph-input" name="paragraph" rows="4" maxlength="10000" placeholder="粘贴 PDF 或网页中的一段英文，然后点选要留下的词。">${esc(draft.paragraph)}</textarea></div><div id="token-area"></div><div id="selected-words"></div>`}<button type="button" class="text-link" data-action="fill-example">${icon('spark')}填入示例</button><p class="error" id="add-error" role="alert"></p><div class="form-footer"><span class="muted" id="draft-count">记录日期：${shortDate(today())}</span><button type="submit" class="btn primary" id="save-entries">保存生词 ${icon('arrow')}</button></div></form>`);if(draft.mode==='paragraph')renderTokens();updateDraftCount();}
function captureDraft(){if(dialogState!=='add')return;draft.source=$('#entry-source')?.value||'';if(draft.mode==='batch')draft.batch=$('#batch-input')?.value||'';else draft.paragraph=$('#paragraph-input')?.value||'';}
function selectedRows(){return Object.values(draft.selected).map(e=>({...e,sentence:(draft.paragraph.match(/[^.!?]+[.!?]?/g)||[draft.paragraph]).find(s=>new RegExp('\\b'+e.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','i').test(s))?.trim()||draft.paragraph}));}
function updateDraftCount(){const rows=draft.mode==='batch'?C.parseBatch(draft.batch):selectedRows();const c=$('#draft-count');if(c)c.textContent=rows.length?`已选 ${rows.length} 条 · ${shortDate(today())}`:`记录日期：${shortDate(today())}`;const btn=$('#save-entries');if(btn)btn.innerHTML=`保存${rows.length?' '+rows.length+' 个':''}生词 ${icon('arrow')}`;}
function renderTokens(){const area=$('#token-area');if(!area)return;const parts=draft.paragraph.split(/([a-zA-Z]+(?:['’-][a-zA-Z]+)*)/g);area.innerHTML=draft.paragraph?`<p class="field-hint">点选下面的词语，再点一次取消。</p><div class="token-area">${parts.map((part,i)=>i%2?`<button type="button" class="token ${draft.selected[C.normalize(part)]?'selected':''}" data-action="token" data-word="${esc(part)}" aria-pressed="${Boolean(draft.selected[C.normalize(part)])}">${esc(part)}</button>`:esc(part)).join('')}</div>`:'';$('#selected-words').innerHTML=Object.entries(draft.selected).map(([key,e])=>`<div class="selected-word"><strong>${esc(e.word)}</strong><input aria-label="${esc(e.word)} 的释义" placeholder="补充本文释义" data-meaning="${esc(key)}" value="${esc(e.meaning)}"><button type="button" class="icon-btn" data-action="token" data-word="${esc(e.word)}" aria-label="取消选择 ${esc(e.word)}">${icon('close')}</button></div>`).join('');updateDraftCount();}
function detail(id){const e=state.entries.find(e=>e.id===id);if(!e)return;dialogState='detail';$('#modal').dataset.entry=id;state.lastEntry=e.id;persist();const related=state.entries.filter(x=>x.id!==id&&C.normalize(x.word)===C.normalize(e.word));showDialog('生词详情',`<div class="detail-hero"><div class="word-top"><h3 class="word">${esc(e.word)}</h3><button class="icon-btn ${e.star?'starred':''}" data-action="detail-star" data-id="${e.id}" aria-label="${e.star?'取消收藏':'收藏'} ${esc(e.word)}" aria-pressed="${e.star}">${icon('star')}</button></div><p class="phonetic">${esc(e.phonetic)}</p><p class="meaning">${esc(e.meaning)||'释义待补充'}</p></div><div class="detail-context"><div class="context-label">原文</div><p class="sentence">${sentenceHTML(e)}</p></div><p class="detail-meta">${esc(e.source)} · ${shortDate(e.created)}记录<br>已回看 ${e.reviews} 次 · 下次回看 ${shortDate(e.due)}${e.sample?'<br><span class="sample-note">演示内容 · 自拟语料</span>':''}</p>${readerDetailExtra(e)}${e.note?`<div class="detail-note">我的笔记：${esc(e.note)}</div>`:''}${related.length?`<div class="section-heading"><h3 class="small">其他原句</h3></div>${related.map(x=>`<div class="encounter"><span class="muted small">${esc(x.source)} · ${shortDate(x.created)}</span><p class="sentence">${sentenceHTML(x)}</p></div>`).join('')}`:''}<div class="detail-actions"><button class="btn ghost danger" data-action="delete-prompt" data-id="${id}">${icon('trash')}删除记录</button><button class="btn" data-action="edit" data-id="${id}">${icon('edit')}编辑记录</button></div>`);}
function edit(id){const e=state.entries.find(x=>x.id===id);if(!e)return;dialogState='edit';showDialog('编辑生词',`<form id="edit-form" data-id="${id}" data-initial-meaning="${esc(e.meaning)}"><div class="form-row"><label for="edit-word">单词或短语</label><input id="edit-word" name="word" value="${esc(e.word)}" required maxlength="150"></div><div class="form-row"><label for="edit-meaning">本文释义</label><input id="edit-meaning" name="meaning" value="${esc(e.meaning)}" maxlength="500"></div><div class="form-row"><label for="edit-sentence">原句</label><textarea id="edit-sentence" name="sentence" rows="3" maxlength="10000">${esc(e.sentence)}</textarea></div><div class="form-row"><label for="edit-source">文章来源</label><input id="edit-source" name="source" value="${esc(e.source)}" maxlength="150"></div><div class="form-row"><label for="edit-note">我的笔记</label><textarea id="edit-note" name="note" rows="2" maxlength="3000">${esc(e.note)}</textarea></div><p id="edit-error" class="error" role="alert"></p><div class="form-footer"><button type="submit" class="btn primary">保存修改 ${icon('check')}</button></div></form>`);}
function settings(){dialogState='settings';showDialog('回顾设置',`<form id="settings-form"><div class="form-row"><label>每组条数</label>${[5,10,15].map(n=>`<label class="settings-choice"><input type="radio" name="batch" value="${n}" ${state.settings.batch===n?'checked':''}>${n} 条</label>`).join('')}</div><div class="form-row"><label for="interval">回顾间隔</label><select id="interval" name="interval">${[1,3,7].map(n=>`<option value="${n}" ${n===state.settings.interval?'selected':''}>${n} 天后</option>`).join('')}</select></div><div class="info-box">“稍后再看”固定为明天，“减少出现”固定为 7 天后。新记录在次日加入回顾。调整条数从下一组开始生效。</div><div class="form-footer"><button type="submit" class="btn primary">保存设置 ${icon('check')}</button></div></form>`);}
function about(){dialogState='about';showDialog('关于拾词',`<div class="about-mark">${icon('logo')}</div><div class="about-section"><h3>数据保存</h3><p>访客记录仅保存在当前浏览器。登录后可跨设备读取已同步的文章、生词和回顾记录；未同步内容仍在本机。</p></div><div class="about-section"><h3>翻译与词典</h3><p>所选词发送至 FreeDictionaryAPI；词语、原句、词典释义与例句发送至 MyMemory 翻译，不发送全文。机器翻译可手动修改。</p></div><div class="about-section"><h3>文章与备份</h3><p>PDF 在本机解析，登录后的文章正文保存到 Supabase。示例语料为自拟。清理浏览器数据前，请同步或导出记录。</p></div><div class="form-footer"><button class="btn" data-action="export">${icon('download')}导出备份</button></div>`);}
function exportData(){const text=JSON.stringify({app:'拾词 Read & Keep',version:1,exportedAt:new Date().toISOString(),...state},null,2);const blob=new Blob([text],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`拾词备份-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已导出');}
document.addEventListener('click',ev=>{
  const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
  if(a==='add'){addDialog();return;}
  if(a==='import-article'){importDialog();return;}
  if(a==='notebook-read'){const book=currentNotebook();if(book?.articleId){state.activeArticle=book.articleId;if(persist())navigate('read');}return;}
  if(a==='close'){captureDraft();captureArticleDraft();if(dialogState==='import'){importTicket++;articleDraft.busy=false;}closeDialog();return;}
  if(a==='about'){about();return;}
  if(a==='detail'){detail(id);return;}
  if(a==='edit'){edit(id);return;}
  if(a==='export'){exportData();return;}
  if(a==='settings'){settings();return;}
  if(a==='star'||a==='detail-star'){const e=state.entries.find(x=>x.id===id);if(!e)return;e.star=!e.star;const ok=persist();render();if(a==='detail-star')detail(id);if(ok)toast(e.star?'已收藏':'已取消收藏');return;}
  if(a==='source'){sourceFilter=el.dataset.source;filter='all';query='';navigate('library');return;}
  if(a==='filter'){filter=el.dataset.filter;render();return;}
  if(a==='group'){groupBy=el.dataset.group;render();return;}
  if(a==='clear-filters'){query='';sourceFilter='';filter='all';render();return;}
  if(a==='start-review'||a==='free-review'||a==='next-session'){beginSession(a==='free-review'||a==='start-review'&&!C.dueEntries(state.entries).length);navigate('review');return;}
  if(a==='rate'){if(!session||session.index>=session.ids.length)return;const entry=state.entries.find(e=>e.id===session.ids[session.index]);session.history.push({...entry});state.entries=state.entries.map(e=>e.id===entry.id?C.reviewed(e,el.dataset.choice,state.settings.interval):e);state.lastEntry=entry.id;session.index++;persist();render();window.scrollTo({top:0,behavior:'instant'});return;}
  if(a==='undo-review'){const previous=session?.history.pop();if(!previous)return;state.entries=state.entries.map(e=>e.id===previous.id?previous:e);session.index--;persist();render();toast('已撤销，可以重新选择');return;}
  if(a==='add-mode'){captureDraft();draft.mode=el.dataset.mode;addDialog();return;}
  if(a==='fill-example'){captureDraft();draft.source='Life beneath the ocean';if(draft.mode==='batch')draft.batch='adapt | 适应 | Marine organisms adapt to changes in their environment.\nscarce | 稀少的 | Food can be scarce in the deep ocean.\nin response to | 作为对……的反应 | Some species move in response to rising temperatures.';else{draft.paragraph='Marine organisms adapt to changes in their environment. Food can be scarce in the deep ocean.';draft.selected={};}addDialog();return;}
  if(a==='token'){const word=el.dataset.word,key=C.normalize(word);if(draft.selected[key])delete draft.selected[key];else draft.selected[key]={word,meaning:state.entries.find(e=>C.normalize(e.word)===key)?.meaning||''};renderTokens();return;}
  if(a==='delete-prompt'){dialogState='delete';const e=state.entries.find(e=>e.id===id);showDialog('删除生词？',`<p class="dialog-subtitle">将移除 ${esc(e.word)} 在「${esc(e.source)}」中的这次遇见。其他原句中的同一个词会保留。</p><button class="btn danger" data-action="delete" data-id="${id}">${icon('trash')}确认删除</button>`);return;}
  if(a==='delete'){const count=deleteRecordIds([id]);if(count===null)return;closeDialog();render();if(count)toast('已删除生词');return;}
});
document.addEventListener('input',ev=>{
  if(ev.target.id==='search'){query=ev.target.value;$('#library-results').innerHTML=libraryResults();bulkSync();}
  if(ev.target.id==='batch-input'){draft.batch=ev.target.value;updateDraftCount();}
  if(ev.target.id==='entry-source')draft.source=ev.target.value;
  if(ev.target.id==='paragraph-input'){draft.paragraph=ev.target.value;for(const key of Object.keys(draft.selected)){if(!draft.paragraph.toLowerCase().includes(key))delete draft.selected[key];}renderTokens();}
  if(ev.target.dataset.meaning){const key=ev.target.dataset.meaning;if(draft.selected[key])draft.selected[key].meaning=ev.target.value;}
});
document.addEventListener('change',ev=>{if(ev.target.id==='source-filter'){sourceFilter=ev.target.value;$('#library-results').innerHTML=libraryResults();bulkSync();}});
document.addEventListener('submit',ev=>{
  if(ev.target.id==='add-form'){ev.preventDefault();captureDraft();const rows=draft.mode==='batch'?C.parseBatch(draft.batch):selectedRows();if(!rows.length){$('#add-error').textContent=draft.mode==='batch'?'请至少输入一个单词或短语。':'请在原文中点选至少一个词。';return;}if(rows.some(r=>r.word.length>150)){$('#add-error').textContent='单个词语太长了，请检查是否误把整段原文放进了词语栏。';return;}const source=draft.source.trim()||'未命名阅读',batch={id:'batch-'+Date.now()+'-'+Math.random().toString(36).slice(2,9),title:source,createdAt:new Date().toISOString()};const result=C.addEntries(state.entries,rows,source,today(),batch);if(!result.added){$('#add-error').textContent='没有可保存的新词，请检查输入。';return;}state.entries=result.entries;const ok=persist();if(!ok){$('#add-error').textContent='尚未保存，请保留输入并重试。';return;}draft={mode:'batch',source:'',batch:'',paragraph:'',selected:{}};closeDialog();render();if(ok)toast(`已保存 ${result.added} 个生词`);}
  if(ev.target.id==='edit-form'){ev.preventDefault();const form=new FormData(ev.target),id=ev.target.dataset.id;const word=form.get('word').trim();if(!word){$('#edit-error').textContent='请输入单词或短语。';return;}state.entries=state.entries.map(e=>{if(e.id!==id)return e;const meaning=form.get('meaning').trim(),sentence=form.get('sentence').trim();const manual=meaning!==(ev.target.dataset.initialMeaning||''),contextChanged=word!==e.word||sentence!==e.sentence;if(manual||contextChanged)cancelEntryTranslation(id);return {...e,...(contextChanged?{lexicon:null}:{}),word,sentence,meaning:manual?meaning:contextChanged?'':e.meaning,source:form.get('source').trim()||'未命名阅读',note:form.get('note').trim(),...(e.articleId&&(manual||contextChanged)?{meaningEdited:manual,translationStatus:manual?'manual':'idle',translationVersion:(e.translationVersion||0)+1,translationError:'',...(contextChanged?{sentenceTranslation:'',lexicon:null,locationStale:Boolean(e.articleId)}:{})}:{})};});const ok=persist();if(!ok){$('#edit-error').textContent='尚未保存，请保留修改并重试。';return;}render();detail(id);if(ok)toast('修改已保存');}
  if(ev.target.id==='settings-form'){ev.preventDefault();const f=new FormData(ev.target);state.settings={...state.settings,batch:Number(f.get('batch')),interval:Number(f.get('interval'))};const ok=persist();if(!ok)return;closeDialog();render();toast('回顾节奏已更新');}
});
$('#modal').addEventListener('cancel',()=>{captureDraft();captureArticleDraft();if(dialogState==='import'){importTicket++;articleDraft.busy=false;}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('storage',ev=>{if(ev.key===KEY&&ev.newValue&&(!window.CloudSession||window.CloudSession.ownsGuest())){try{const updated=JSON.parse(ev.newValue);if(Array.isArray(updated.entries)){state=updated;persistedState=JSON.parse(JSON.stringify(updated));render();}}catch{}}});
render();
if(!storageOK)setTimeout(()=>toast('浏览器存储不可用，请及时导出备份'),500);
